import json
from typing import Tuple, Dict

data = [
    {"id": 1, "name": "雞肉捲", "quantity": 10, "category": "食品"},
    {"id": 2, "name": "可樂", "quantity": 3, "category": "飲料"},
    {"id": 3, "name": "玉米熱狗", "quantity": 7, "category": "食品"},
    {"id": 4, "name": "冰奶茶", "quantity": 2, "category": "飲料"},
    {"id": 5, "name": "紙杯", "quantity": 15, "category": "其他"}
]
next_id = 6

def handle(method: str, path: str, body: bytes) -> Tuple[int, Dict]:
    global data, next_id

    if method == "GET" and path == "/items":
        return (200, data)

    elif method == "POST" and path == "/items":
        try:
            payload = json.loads(body.decode())
            new_item = {
                "id": next_id,
                "name": payload["name"],
                "quantity": payload["quantity"],
                "category": payload.get("category", "其他")
            }
            data.append(new_item)
            next_id += 1
            return (201, new_item)
        except Exception as e:
            return (400, {"error": str(e)})

    elif method == "PUT" and path.startswith("/items/"):
        try:
            item_id = int(path.split("/")[3])
            payload = json.loads(body.decode())
            delta = payload["delta"]
            for item in data:
                if item["id"] == item_id:
                    item["quantity"] += delta
                    return (200, item)
            return (404, {"error": "商品未找到"})
        except Exception as e:
            return (400, {"error": str(e)})

    elif method == "DELETE" and path.startswith("/items/"):
        try:
            item_id = int(path.split("/")[3])
            for i, item in enumerate(data):
                if item["id"] == item_id:
                    data.pop(i)
                    return (200, {"message": "商品已刪除"})
            return (404, {"error": "商品未找到"})
        except Exception as e:
            return (400, {"error": str(e)})

    elif method == "GET" and path.startswith("/items/category/"):
        try:
            category = path.split("/")[4]
            filtered_items = [item for item in data if item["category"] == category]
            return (200, filtered_items)
        except Exception as e:
            return (400, {"error": str(e)})

    else:
        return (404, {"error": "端點不存在"})

