document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('itemForm');
    const itemsList = document.getElementById('itemsList');
    const categoryFilter = document.getElementById('categoryFilter');

    // 獲取所有商品
    async function fetchItems(category = 'all') {
        try {
            let url = 'api/items';
            if (category !== 'all') {
                url += `/category/${category}`;
            }
            const response = await fetch(url);
            const items = await response.json();
            displayItems(items);
        } catch (error) {
            console.error('獲取商品時出錯:', error);
        }
    }

    // 顯示商品列表
    function displayItems(items) {
        itemsList.innerHTML = '';
        if (items.length === 0) {
            itemsList.innerHTML = '<p>目前沒有商品</p>';
            return;
        }

        const table = document.createElement('table');
        table.innerHTML = `
            <thead>
                <tr>
                    <th>商品名稱</th>
                    <th>數量</th>
                    <th>操作</th>
                </tr>
            </thead>
            <tbody>
                ${items.map(item => `
                    <tr class="${item.quantity < 5 ? 'low-stock' : ''}">
                        <td>${item.name}</td>
                        <td>${item.quantity}</td>
                        <td>
                            <button onclick="updateQuantity(${item.id}, -1)">-</button>
                            <button onclick="updateQuantity(${item.id}, 1)">+</button>
                            <button onclick="deleteItem(${item.id})">刪除</button>
                        </td>
                    </tr>
                `).join('')}
            </tbody>
        `;
        itemsList.appendChild(table);
    }

    // 新增商品
    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const name = document.getElementById('itemName').value;
        const quantity = parseInt(document.getElementById('itemQuantity').value);

        try {
            await fetch('api/items', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name, quantity })
            });
            form.reset();
            fetchItems(categoryFilter.value); // 重新獲取並顯示商品
        } catch (error) {
            console.error('新增商品時出錯:', error);
        }
    });

    // 更新數量
    window.updateQuantity = async (id, delta) => {
        try {
            await fetch(`api/items/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ delta })
            });
            fetchItems(categoryFilter.value); // 重新獲取並顯示商品
        } catch (error) {
            console.error('更新數量時出錯:', error);
        }
    };

    // 刪除商品
    window.deleteItem = async (id) => {
        if (!confirm('確定要刪除這個商品嗎？')) return;
        try {
            await fetch(`api/items/${id}`, { method: 'DELETE' });
            fetchItems(categoryFilter.value); // 重新獲取並顯示商品
        } catch (error) {
            console.error('刪除商品時出錯:', error);
        }
    };

    // 分類篩選
    categoryFilter.addEventListener('change', () => {
        fetchItems(categoryFilter.value);
    });

    // 初始化
    fetchItems();
});

